#include "CymbalEngine.h"
namespace cymbalforge {
void CymbalParameters::copyFrom(const CymbalParameters& source) noexcept { velocity=source.velocity.load();position=source.position.load();variation=source.variation.load();velocityTone=source.velocityTone.load();brightness=source.brightness.load();decay=source.decay.load();choke=source.choke.load();complexity=source.complexity.load();shimmer=source.shimmer.load();swell=source.swell.load();noise=source.noise.load();noiseTone=source.noiseTone.load();noiseDecay=source.noiseDecay.load();subLevel=source.subLevel.load();subTune=source.subTune.load();subDecay=source.subDecay.load();subDelay=source.subDelay.load();sub2Level=source.sub2Level.load();sub2Tune=source.sub2Tune.load();sub2Decay=source.sub2Decay.load();sub2Delay=source.sub2Delay.load();filterCutoff=source.filterCutoff.load();filterResonance=source.filterResonance.load();filterEnvAmount=source.filterEnvAmount.load();filterEnvDecay=source.filterEnvDecay.load();modLfoRate=source.modLfoRate.load();modLfoDepth=source.modLfoDepth.load();tempoBpm=source.tempoBpm.load();drive=source.drive.load();transient=source.transient.load();width=source.width.load();limiter=source.limiter.load();reverb=source.reverb.load();gain=source.gain.load();filterMode=source.filterMode.load();modTarget=source.modTarget.load();lfoSync=source.lfoSync.load();exciter=source.exciter.load();midiPositionMap=source.midiPositionMap.load();modes=source.modes.load();model=source.model.load();for(int i=0;i<4;++i){sampleLevel[(size_t)i]=source.sampleLevel[(size_t)i].load();sampleTune[(size_t)i]=source.sampleTune[(size_t)i].load();sampleAttack[(size_t)i]=source.sampleAttack[(size_t)i].load();sampleDecay[(size_t)i]=source.sampleDecay[(size_t)i].load();sampleSustain[(size_t)i]=source.sampleSustain[(size_t)i].load();sampleRelease[(size_t)i]=source.sampleRelease[(size_t)i].load();sampleDelay[(size_t)i]=source.sampleDelay[(size_t)i].load();sampleLfoRate[(size_t)i]=source.sampleLfoRate[(size_t)i].load();sampleLfoDepth[(size_t)i]=source.sampleLfoDepth[(size_t)i].load();sampleLoop[(size_t)i]=source.sampleLoop[(size_t)i].load();} }
ImpactControls CymbalParameters::snapshot() const noexcept { ImpactControls c; c.brightness=brightness.load(); c.decay=decay.load(); c.choke=choke.load(); c.complexity=complexity.load(); c.shimmer=shimmer.load(); c.swell=swell.load(); c.noise=noise.load(); c.noiseTone=noiseTone.load(); c.noiseDecay=noiseDecay.load(); c.subLevel=subLevel.load(); c.subTune=subTune.load(); c.subDecay=subDecay.load(); c.subDelay=subDelay.load(); c.sub2Level=sub2Level.load(); c.sub2Tune=sub2Tune.load(); c.sub2Decay=sub2Decay.load(); c.sub2Delay=sub2Delay.load(); c.filterCutoff=filterCutoff.load(); c.filterResonance=filterResonance.load(); c.filterEnvAmount=filterEnvAmount.load(); c.filterEnvDecay=filterEnvDecay.load(); c.filterMode=filterMode.load(); c.modLfoRate=modLfoRate.load(); c.modLfoDepth=modLfoDepth.load(); c.tempoBpm=tempoBpm.load(); c.lfoSync=lfoSync.load(); c.modTarget=modTarget.load(); c.exciter=exciter.load(); c.model=model.load(); c.modes=modes.load(); for(int i=0;i<4;++i) c.samples[(size_t)i]={sampleLevel[(size_t)i].load(),sampleTune[(size_t)i].load(),sampleAttack[(size_t)i].load(),sampleDecay[(size_t)i].load(),sampleSustain[(size_t)i].load(),sampleRelease[(size_t)i].load(),sampleDelay[(size_t)i].load(),sampleLfoRate[(size_t)i].load(),sampleLfoDepth[(size_t)i].load(),sampleLoop[(size_t)i].load()!=0}; return c; }
void CymbalEngine::prepare(double rate, int block) { formats.registerBasicFormats(); for(auto& impact:impacts) impact.prepare(rate); juce::dsp::ProcessSpec s{rate, (juce::uint32) block, 2}; reverb.prepare(s); }
void CymbalEngine::strike(float v, float p) { const auto amount=parameters.variation.load(); v=juce::jlimit(0.0f,1.0f,v*(1.0f+(variationRandom.nextFloat()*2.0f-1.0f)*amount*.18f)); p=juce::jlimit(0.02f,.98f,p+(variationRandom.nextFloat()*2.0f-1.0f)*amount*.12f); auto controls=parameters.snapshot(); controls.brightness=juce::jlimit(0.0f,1.0f,controls.brightness*(1.0f-parameters.velocityTone.load()*.75f+v*parameters.velocityTone.load()*.75f)); impacts[(size_t)nextImpactVoice].trigger(v,p,controls); nextImpactVoice=(nextImpactVoice+1)%maxImpactVoices; }
void CymbalEngine::strikeFromMidi(int note, float velocity) { auto position=parameters.position.load(); if(parameters.midiPositionMap.load()!=0) position=juce::jmap(float(note),36.0f,96.0f,.03f,.97f); strike(velocity,juce::jlimit(.03f,.97f,position)); }
void CymbalEngine::release() { for (auto& impact : impacts) impact.release(); }
void CymbalEngine::setSampleSlot(int slot, std::shared_ptr<const ImpactSampleData> sample, const juce::File& file) { if(!juce::isPositiveAndBelow(slot,4)) return; for(auto& impact:impacts) impact.setSample(slot,sample); sampleFiles[(size_t)slot]=file; }
bool CymbalEngine::loadSampleSlot(int slot,const juce::File& file) { auto reader=std::unique_ptr<juce::AudioFormatReader>(formats.createReaderFor(file)); if(!reader || !juce::isPositiveAndBelow(slot,4)) return false; auto sample=std::make_shared<ImpactSampleData>(); sample->audio.setSize(juce::jmin(2,(int)reader->numChannels),int(reader->lengthInSamples)); reader->read(&sample->audio,0,sample->audio.getNumSamples(),0,true,true); sample->sampleRate=reader->sampleRate; setSampleSlot(slot,sample,file); return true; }
void CymbalEngine::clearSampleSlot(int slot) { setSampleSlot(slot,{},{}); }
juce::File CymbalEngine::sampleFile(int slot) const { return juce::isPositiveAndBelow(slot,4)?sampleFiles[(size_t)slot]:juce::File{}; }
void CymbalEngine::render(juce::AudioBuffer<float>& buffer, int start, int count) { buffer.clear(start,count); auto gain=parameters.gain.load(),drive=parameters.drive.load(),transient=parameters.transient.load(),width=parameters.width.load(),limit=.25f+.74f*parameters.limiter.load(); for(int i=0;i<count;++i) { std::array<float,2> dry{}; for(auto& impact:impacts) if(impact.active()){auto voice=impact.render();dry[0]+=voice[0];dry[1]+=voice[1];} auto left=dry[0]+(dry[0]-previousL)*transient;auto right=dry[1]+(dry[1]-previousR)*transient;previousL=dry[0];previousR=dry[1]; auto mid=(left+right)*.5f,side=(left-right)*(.25f+width*.75f);left=mid+side;right=mid-side; if(drive>.0001f){auto amount=1.0f+drive*8.0f;left=std::tanh(left*amount)/amount;right=std::tanh(right*amount)/amount;} left=juce::jlimit(-limit,limit,left)*gain;right=juce::jlimit(-limit,limit,right)*gain; buffer.setSample(0,start+i,left); buffer.setSample(1,start+i,right); } juce::dsp::AudioBlock<float> b(buffer); auto sub=b.getSubBlock((size_t)start,(size_t)count); juce::dsp::ProcessContextReplacing<float> c(sub); juce::dsp::Reverb::Parameters p; p.wetLevel=parameters.reverb.load()*0.35f; p.dryLevel=1.0f; p.roomSize=.55f; reverb.setParameters(p); reverb.process(c); }
}
